Async and the Event Loop — Worked Exampl:
The exact interleaving of sync, micro and macro work, including the second-tick surprise:

```js
setTimeout(() => console.log('A: macrotask'), 0);
queueMicrotask(() => console.log('B: microtask'));
(async () => {
  console.log('C: async body start');
  await null;
  console.log('D: after await');
})();
Promise.resolve().then(() => console.log('E: then'));
console.log('F: sync end');

// C: async body start
// F: sync end
// B: microtask
// D: after await
// E: then
// A: macrotask
```

Because microtasks drain fully, a self-scheduling microtask starves timers and the UI:

```js
let n = 0;
const spinMicro = () => {
  if (n++ < 5) queueMicrotask(spinMicro);          // safe, bounded
};
setTimeout(() => console.log('timer'), 0);
spinMicro();
console.log('sync done');

// unbounded version (do not ship): queueMicrotask(function again() { queueMicrotask(again); });
```

Awaiting inside a loop and parallelising the same work:

```js
const delay = (ms, v) => new Promise((r) => setTimeout(() => r(v), ms));

const t0 = performance.now();
const seq = [];
for (const ms of [40, 40, 40]) seq.push(await delay(ms, ms));
console.log('sequential', Math.round(performance.now() - t0), seq);   // ~120

const t1 = performance.now();
const par = await Promise.all([delay(40, 1), delay(40, 2), delay(40, 3)]);
console.log('parallel', Math.round(performance.now() - t1), par);      // ~40
```

Modules and Code Organisation — Worked E:
Named exports are live bindings; a default export is a snapshot of a value:

```js
// state.js
let current = 0;
export const read = () => current;
export const bump = () => { current += 1; };
export default current;      // captured at evaluation time

// main.js
import snapshot, { read, bump } from './state.js';
console.log(read(), snapshot);   // 0 0
bump();
bump();
console.log(read(), snapshot);   // 2 0 — the binding moved, the snapshot did not
```

Circular imports work only because bindings are resolved lazily; a value used at module top level will be undefined:

```js
// a.js
export const name = 'a';
import { describe } from './b.js';
console.log('a sees:', describe);            // undefined at this point

// b.js
import { name } from './a.js';
export const describe = `b from ${name}`;    // fine: evaluated after a.js's name exists
export function later() { return `b from ${name}`; }
```

The barrel file is convenient and expensive; import the module you need when it matters:

```js
// index.js — pulls in every module for one import
export * from './parser.js';
export * from './renderer.js';

// preferred in hot paths
import { parse } from './parser.js';

// lazy, when the module is large or conditional
const { render } = await import('./renderer.js');
```

DOM and Events — Worked Examples:
Read-then-write batching is the difference between one layout and hundreds:

```js
const rows = [...document.querySelectorAll('.row')];

// read all first
const widths = rows.map((r) => r.getBoundingClientRect().width);
const tallest = Math.max(...rows.map((r) => r.offsetHeight));

// then write all
rows.forEach((r, i) => {
  r.style.width = `${Math.max(widths[i], 120)}px`;
  r.style.height = `${tallest}px`;
});
```

Delegation plus `closest` keeps one listener working for any number of future rows:

```js
const table = document.querySelector('#grid');
table.addEventListener('click', (event) => {
  const cell = event.target.closest('td[data-id]');
  if (!cell) return;
  table.querySelectorAll('td.is-selected').forEach((td) => td.classList.remove('is-selected'));
  cell.classList.add('is-selected');
  table.dispatchEvent(new CustomEvent('cell:pick', { detail: { id: cell.dataset.id }, bubbles: true }));
});
```

The listener options that prevent the two classic performance bugs:

```js
// passive: the listener promises never to call preventDefault, so scrolling is not blocked
window.addEventListener('touchstart', onTouch, { passive: true });

// once: removed automatically, which avoids a manual guard flag
document.querySelector('#accept').addEventListener('click', onAccept, { once: true });

// signal: one controller removes a whole group at once
const controller = new AbortController();
for (const el of document.querySelectorAll('.draggable')) {
  el.addEventListener('pointerdown', onDown, { signal: controller.signal });
}
controller.abort();
```

Networking and Storage — Worked Examples:
Conditional requests turn a large response into a small 304, and the ETag is the key:

```js
let etag = localStorage.getItem('items:etag') ?? '';
const res = await fetch('/api/items', { headers: etag ? { 'if-none-match': etag } : {} });

if (res.status === 304) {
  console.log('unchanged, using cache');
} else if (res.ok) {
  const data = await res.json();
  etag = res.headers.get('etag') ?? '';
  localStorage.setItem('items', JSON.stringify(data));
  localStorage.setItem('items:etag', etag);
}
```

A stale-while-revalidate cache in twenty lines, with a versioned key so a schema change cannot serve old shapes:

```js
const KEY = 'items:v2';

async function loadItems({ maxAgeMs = 60_000 } = {}) {
  const raw = localStorage.getItem(KEY);
  const cached = raw ? JSON.parse(raw) : null;
  const fresh = cached && Date.now() - cached.at < maxAgeMs;
  if (fresh) return cached.value;

  const value = await fetch('/api/items').then((r) => r.json());
  localStorage.setItem(KEY, JSON.stringify({ at: Date.now(), value }));
  return value;
}
```

Retry only the failures worth retrying, and bound the waiting:

```js
const RETRY = new Set([408, 429, 500, 502, 503, 504]);

async function get(url, attempts = 3) {
  for (let i = 1; ; i++) {
    const res = await fetch(url, { signal: AbortSignal.timeout(8000) });
    if (res.ok) return res.json();
    if (i >= attempts || !RETRY.has(res.status)) {
      throw new Error(`${res.status} ${res.statusText}`);
    }
    const wait = Math.min(2000, 200 * 2 ** (i - 1)) * (0.5 + Math.random() / 2);
    await new Promise((r) => setTimeout(r, wait));
  }
}
```

