console.log(values, positionals);
```

Reading a whole tree with a bounded depth, and skipping what cannot be read:

```js
import { readdir, stat } from 'node:fs/promises';
import { join } from 'node:path';

async function walk(dir, depth = 0, maxDepth = 6, out = []) {
  if (depth > maxDepth) return out;
  for (const entry of await readdir(dir, { withFileTypes: true }).catch(() => [])) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) await walk(full, depth + 1, maxDepth, out);
    else if (entry.isFile() && full.endsWith('.json')) out.push(full);
  }
  return out;
}
console.log(await walk('.'));
```

A processing pipeline that streams instead of loading everything:

```js
import { createReadStream, createWriteStream } from 'node:fs';
import { pipeline } from 'node:stream/promises';
import { Transform } from 'node:stream';
import { createGzip } from 'node:zlib';

await pipeline(
  createReadStream('access.log'),
  new Transform({
    transform(chunk, _enc, cb) {
      const lines = String(chunk).split('\n').filter((l) => !l.includes('/health'));
      cb(null, lines.join('\n') + '\n');
    },
  }),
  createGzip(),
  createWriteStream('access.clean.log.gz'),
);
```

Design Patterns — Worked Examples:
Repository plus unit of work keeps persistence out of the domain, and both are plain objects:

```js
const createOrderRepo = (rows = new Map()) => ({
  byId: (id) => rows.get(id) ?? null,
  save: (order) => (rows.set(order.id, order), order),
  all: () => [...rows.values()],
  count: () => rows.size,
});

const repo = createOrderRepo();
repo.save({ id: 'o1', total: 120 });
repo.save({ id: 'o2', total: 40 });
console.log(repo.byId('o2'), repo.count());
```

Strategy selected by data, with a default that cannot be undefined:

```js
const SHIPPING = {
  standard: (w) => 4 + w * 0.4,
  express: (w) => 12 + w * 0.9,
  pickup: () => 0,
};
const shippingFor = (method, weight) => (SHIPPING[method] ?? SHIPPING.standard)(weight);
console.log(shippingFor('express', 10), shippingFor('nope', 10), shippingFor('pickup', 10));
```

A decorator chain wraps behaviour without subclassing, and `once`/`memoize` are the ones you reuse:

```js
const withRetry = (fn, attempts = 3) => async (...args) => {
  let last;
  for (let i = 0; i < attempts; i++) {
    try { return await fn(...args); }
    catch (err) { last = err; }
  }
  throw last;
};

const withTiming = (fn, label = 'call') => async (...args) => {
  const t = performance.now();
  try { return await fn(...args); }
  finally { console.log(`${label}: ${(performance.now() - t).toFixed(1)}ms`); }
};

const load = withTiming(withRetry(async (id) => ({ id })), 'load');
console.log(await load(7));
```

Common Bugs and How to Fix Them:
Five defects you will actually meet, with the fix beside each:

```js
// 1. async in forEach — the loop does not wait
[1, 2].forEach(async (n) => { await save(n); });
for (const n of [1, 2]) await save(n);

// 2. string sort
[10, 9, 80].sort();                       // [10, 80, 9]
[10, 9, 80].sort((a, b) => a - b);        // [9, 10, 80]

// 3. shared reference through a shallow copy
const a = { list: [] };
const b = { ...a };
b.list.push(1);                           // a.list is [1] too
const c = structuredClone(a);             // deep, and handles Date/Map/Set

// 4. NaN comparisons
const x = Number('nope');
x === NaN;                                 // always false
Number.isNaN(x);                           // true

// 5. floating point equality
0.1 + 0.2 === 0.3;                         // false
Math.abs(0.1 + 0.2 - 0.3) < 1e-9;          // true
```

Three more that only bite in production:

```js
// 6. a listener added per render, never removed
useEffect(() => {
  const onResize = () => {};
  window.addEventListener('resize', onResize);
  return () => window.removeEventListener('resize', onResize);   // the cleanup
}, []);

// 7. an unhandled rejection that silently kills the process
process.on('unhandledRejection', (err) => { console.error('unhandled', err); process.exit(1); });

// 8. reading a body twice
const res = await fetch(url);
const data = await res.clone().json();
const text = await res.text();      // still readable
```

The pattern behind every one of these: a shared mutable reference, an implicit conversion, or an assumption that an operation is atomic when it is not. Naming which of the three you are looking at finds the bug faster than reading the stack.

Performance, Security and Quality Recipe:
Memoise by a derived key, and bound the cache so it cannot grow forever:

```js
function memoize(fn, keyOf = (...a) => JSON.stringify(a), limit = 500) {
  const cache = new Map();
  return (...args) => {
    const key = keyOf(...args);
    if (cache.has(key)) {
      const value = cache.get(key);
      cache.delete(key);
      cache.set(key, value);          // refresh recency
      return value;
    }
    const value = fn(...args);
    cache.set(key, value);
    if (cache.size > limit) cache.delete(cache.keys().next().value);
    return value;
  };
}

const slow = memoize((n) => n * n);
console.log(slow(4), slow(4), slow.size);
```

Debounce and throttle, with the cancel path that unmounting needs:

```js
function debounce(fn, wait) {
  let timer = null;
  const wrapped = (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => { timer = null; fn(...args); }, wait);
  };
  wrapped.cancel = () => clearTimeout(timer);
  return wrapped;
}

const throttle = (fn, ms) => {
  let last = 0;
  return (...args) => {
    const now = Date.now();
    if (now - last >= ms) { last = now; fn(...args); }
  };
};
```

Escaping and allow-listing, which is the whole of input safety in two functions:

```js
const escapeHtml = (s) => String(s).replace(/[&<>"']/g, (c) =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const SAFE = new Set(['https:', 'mailto:']);
const safeUrl = (input, base = 'https://example.com') => {
  try {
    const url = new URL(input, base);
    return SAFE.has(url.protocol) ? url.toString() : null;
  } catch { return null; }
};

console.log(escapeHtml('<script>'), safeUrl('javascript:alert(1)'), safeUrl('/docs'));
```

Quality recipes worth keeping: assert on values not on log output, inject the clock and the random source so tests are deterministic, and give every timeout, retry and queue an explicit bound.
